#include "stdafx.h"#include "FBDsConverter.h"#include "FBDsConverterDoc.h"#include "ParsingHelp.h"#include <fstream>#include <algorithm>#ifdef _DEBUG#define new DEBUG_NEW#undef THIS_FILEstatic char THIS_FILE[] = __FILE__;#endifusing namespace std;void CFBDsConverterDoc::ReadFindInfo(){  {    CVSRow csvReader;    ifstream Fd( m_szObjOnSheet.c_str(), std::ios_base::in);    while( Fd >> csvReader )    {      theApp.m_SheetTree.push_back( tSheetInfo_::value_type() );      tSheetInfo_::value_type &rec = theApp.m_SheetTree.back();      rec.szFile = csvReader[0];      rec.szSheet = csvReader[1];      rec.szPage = csvReader[2];      for( size_t i=3; i<csvReader.size(); i++ )      {        if( !theApp.m_ObjOnSheets.empty() )        {          std::vector<std::string>::iterator it = find( theApp.m_ObjOnSheets[ csvReader[i] ].begin(), theApp.m_ObjOnSheets[ csvReader[i] ].end(), rec.szFile );          if( it!=theApp.m_ObjOnSheets[ csvReader[i] ].end() )            continue;        }        theApp.m_ObjOnSheets[ csvReader[i] ].push_back( rec.szFile );      }    }  }  {    CVSRow csvReader(',');    ifstream Fd( m_szWVars.c_str(), std::ios_base::in);    while( Fd >> csvReader )    {      if( csvReader.size()<2 )        continue;      size_t ass = csvReader[1].find('=');      if( string::npos==ass )        continue;      int id = atoi( csvReader[1].substr(ass+1).c_str() );      if( !id )        continue;      m_WVarToVariable[id].push_back( csvReader[0] );    }  }}void CFBDsConverterDoc::OpenEmf( LPCTSTR lpszFileName ){  CStringA szF;  szF.Format( "%sFBDs\\%s", m_szRootDir.c_str(), lpszFileName );  theApp.OpenDocumentFile( szF );}